Section SDEC.
  Variables (RNG : footprint) (Q : machine_state -> Prop) (m0 : amem) (SPV FF DST dcap S0 DT lo RLO RHI SB SN : Z) (bs : list Z)
            (d : dtable) (gp tp : word) (FR : bvmap 5 word) (fc : bv 32) (j48 jd : list byte).
  Notation SP1 := (SPAf SPV).
  Notation tl := (dt_tableLog d).
  Notation TB := (DT + 4).
  Hypothesis FC8 : rw_cells asegs m0 (SP1 + 8) [C8 (Z_to_bv 64 DST); C8 (Z_to_bv 64 2147450880); C8 (Z_to_bv 64 FF)].
  Hypothesis FOBJ : rw_cells asegs m0 (SP1 + 48) [CB 72 j48].
  Hypothesis STK : stk asegs m0 lo SP1.
  Hypothesis BOT : ATOP + 4096 <= lo.
  Hypothesis LO : lo <= SP1 - DEC_STACK.
  Hypothesis SP16 : SPV mod 16 = 0.
  Hypothesis SPH : SPV + 16 <= 2^47.
  Hypothesis ZOBJ : zshadow m0 (SP1 + 48) 72.
  Hypothesis SHC : shclean m0 (SP1 + 80) (SP1 + 120) RLO RHI.
  Hypothesis RRH : rng RNG (shad RLO) (shad RHI - shad RLO).
  Hypothesis RO48 : rng RNG (SP1 + 48) 72.
  Hypothesis RO48s : rng RNG (shad (SP1 + 48)) 9.
  Hypothesis RO8 : rng RNG (SP1 + 8) 24.
  Hypothesis HTL : 5 <= tl <= 12.
  Hypothesis HCELLS : zlen (dt_cells d) = 2^tl.
  Hypothesis HCOK : RF_huf_fdw_sm.cells_ok tl (dt_cells d).
  Hypothesis FM : dt_fastMode d = 0.
  Hypothesis DTH : rw_cells asegs m0 DT [C2 (Z_to_bv 64 tl); C2 (Z_to_bv 64 0)].
  Hypothesis TBB : bytes_at asegs m0 TB (concat (map fse_cell_bytes (dt_cells d))).
  Hypothesis HDT : ablk DT (DT + 4 + 4 * 2^tl).
  Hypothesis DT4 : DT mod 4 = 0.
  Hypothesis ZDT : zshadow m0 DT (4 + 4 * 2^tl).
  Hypothesis RDT : rng RNG DT (4 + 4 * 2^tl).
  Hypothesis RDTs : rng RNG (shad DT) (nshad (4 + 4 * 2^tl + DT mod 8)).
  Hypothesis SRC : bytes_at asegs m0 S0 (map (Z_to_bv 8) bs).
  Hypothesis BY : Forall (fun c => 0 <= c < 256) bs.
  Hypothesis NS : zlen bs <= 65536.
  Hypothesis SEQ : SB + SN = S0 + zlen bs.
  Hypothesis SB0 : 0 <= SB.
  Hypothesis SN0 : 0 <= SN.
  Hypothesis HS0 : ablk S0 (S0 + zlen bs).
  Hypothesis S8 : S0 + 8 <= 2^47.
  Hypothesis S16 : 16 <= S0.
  Hypothesis USRC : unpoisoned m0 S0 (S0 + zlen bs).
  Hypothesis RS : rng RNG S0 (zlen bs).
  Hypothesis RSs : rng RNG (shad S0) (nshad (zlen bs + S0 mod 8)).
  Hypothesis OUTA : u8arr asegs m0 DST jd.
  Hypothesis LJD : zlen jd = dcap.
  Hypothesis DC : 0 <= dcap <= 255.
  Hypothesis HDST : ablk DST (DST + dcap).
  Hypothesis DST3 : 3 <= DST.
  Hypothesis ZDST : zshadow m0 DST dcap.
  Hypothesis RDST : rng RNG DST dcap.
  Hypothesis RDSTs : rng RNG (shad DST) (nshad (dcap + DST mod 8)).
  Hypothesis DJ2 : DST + dcap <= S0 \/ S0 + zlen bs <= DST.
  Hypothesis DJ1 : DST + dcap <= DT \/ DT + 4 + 4 * 2^tl <= DST.
  Hypothesis DJ3 : S0 + zlen bs <= DT \/ DT + 4 + 4 * 2^tl <= S0.
  Hypothesis MI : mem_inv asegs m0.
  Hypothesis RTC : artcells m0.
  Hypothesis ZMK : zshadow m0 ABIT_MASK 128.
  Hypothesis RSTK : rng RNG lo (SP1 - lo).
  Hypothesis RI : rng_aimg RNG.
  Hypothesis RISH : rng_aimg_sh RNG.
  Hypothesis RESOK : dres_ok (decompress_usingDTable bs d dcap false).
  Notation W0 := [(lo, SP1); (SP1 + 48, SP1 + 120); (DST, DST + dcap)].
  Hypothesis K : forall m1 rv (j48' : list byte) (y1 y5 y6 y7 y10 y11 y12 y13 y14 y16 y20 y21 y22 y23 y24 y25 y26 y27 y28 y29 y30 y31 : word),
       munch W0 m0 m1 -> wmono asegs m0 m1 ->
       mem_inv asegs m1 -> stk asegs m1 lo SP1 -> rw_cells asegs m1 (SP1 + 48) [CB 72 j48'] ->
       dresA DST dcap (decompress_usingDTable bs d dcap false) m1 rv -> 0 <= rv < 2^64 ->
       evtF asegs RNG Q
         (MS (mkR y1 (Z_to_bv 64 SP1) gp tp y5 y6 y7 (Z_to_bv 64 SPV) (Z_to_bv 64 SP1) y10 y11 y12 y13 y14
                  (Z_to_bv 64 rv) y16 (Z_to_bv 64 FF) (Z_to_bv 64 FF) (Z_to_bv 64 (Z.shiftr FF 3 + 2147450880))
                  y20 y21 y22 y23 y24 y25 y26 y27 y28 y29 y30 y31)
             FR (Z_to_bv 64 0x960bc) fc None m1 (seg_rom asegs)).

  (* [comment removed for export] *)
  Lemma sdA_exit : forall m1 rv (j48' : list byte)
      (y1 y5 y6 y7 y10 y11 y12 y13 y14 y16 y17 y20 y21 y22 y23 y24 y25 y26 y27 y28 y29 y30 y31 : word),
    munch W0 m0 m1 -> wmono asegs m0 m1 -> mem_inv asegs m1 -> stk asegs m1 lo SP1 -> rw_cells asegs m1 (SP1 + 48) [CB 72 j48'] ->
    dresA DST dcap (decompress_usingDTable bs d dcap false) m1 rv -> 0 <= rv < 2^64 ->
    evtF asegs RNG Q
      (MS (mkR y1 (Z_to_bv 64 SP1) gp tp y5 y6 y7 (Z_to_bv 64 SPV) (Z_to_bv 64 SP1) y10 y11 y12 y13 y14
               (Z_to_bv 64 rv) y16 y17 (Z_to_bv 64 FF) (Z_to_bv 64 (Z.shiftr FF 3 + 2147450880))
               y20 y21 y22 y23 y24 y25 y26 y27 y28 y29 y30 y31)
          FR (Z_to_bv 64 0x960b8) fc None m1 (seg_rom asegs)).
