  Lemma sdA_tail : forall r R m2 (w48 w64 w80 w88 w96 : word) (jp junk : list byte)
      (y1 y10 y11 y12 y21 y22 y23 y26 y28 y29 y30 y31 : word),
    tail_loop bs d dcap false (Datatypes.S (Z.to_nat dcap)) r = R -> R = decompress_usingDTable bs d dcap false ->
    RF_huf_fdw_st.res_ok R ->
    bitd_ok bs (de_bd r) -> bd_bits (de_bd r) <= 2^29 -> zlen (de_out r) <= dcap -> Forall (fun c => 0 <= c < 256) (de_out r) ->
    u8arr asegs m2 DST (map (Z_to_bv 8) (de_out r) ++ junk) -> zlen junk = dcap - zlen (de_out r) ->
    munch W0 m0 m2 -> wmono asegs m0 m2 -> mem_inv asegs m2 -> stk asegs m2 lo SP1 -> 0 < zlen bs ->
    rw_cells asegs m2 (SP1 + 48) [C8 w48; C8 (Z_to_bv 64 TB); C8 w64; C8 (Z_to_bv 64 TB); C8 w80; C4 w88; CB 4 jp; C8 w96;
                                  C8 (Z_to_bv 64 S0); C8 (Z_to_bv 64 (S0 + 8))] ->
    evtF asegs RNG Q
      (MS (mkR y1 (Z_to_bv 64 SP1) gp tp (Z_to_bv 64 (bd_cont (de_bd r))) (Z_to_bv 64 (bd_bits (de_bd r))) (Z_to_bv 64 (de_s2 r))
               (Z_to_bv 64 SPV) (Z_to_bv 64 SP1) y10 y11 y12 (Z_to_bv 64 (de_s1 r)) (Z_to_bv 64 (S0 + 8)) (Z_to_bv 64 64)
               (Z_to_bv 64 135040) (Z_to_bv 64 (DST + zlen (de_out r))) (Z_to_bv 64 FF) (Z_to_bv 64 (Z.shiftr FF 3 + 2147450880))
               (Z_to_bv 64 (bd_regA S0 (de_bd r))) y21 y22 y23 (Z_to_bv 64 (DST + dcap)) (Z_to_bv 64 (DST + dcap - 3)) y26
               (Z_to_bv 64 2147450880) y28 y29 y30 y31)
          FR (Z_to_bv 64 0x9699c) fc None m2 (seg_rom asegs)).
Proof.
