  Ltac sdr3_side :=
    lazymatch goal with
    | |- munch W0 m0 ?mm' =>
        lazymatch goal with MQ : munch [(SP1 + 80, SP1 + 88)] ?mq mm', MW : munch W0 m0 ?mq |- _ =>
          eapply munch_trans; [exact MW| eapply munch_weaken; [| exact MQ]]; intros x Hx; cbn [outside] in *;
          pose proof (spaf_props SPV SP16); lia end
    | |- wmono asegs m0 ?mm' => eapply wmono_trans; eassumption
    | |- stk asegs ?mm' lo SP1 =>
        lazymatch goal with MQ : munch [(SP1 + 80, SP1 + 88)] ?mq mm' |- _ =>
          eapply stk_transport; [eassumption| exact MQ| eassumption|];
          intros x Hx; left; cbn [outside]; split; [pose proof (spaf_props SPV SP16); lia| exact I] end
    | |- u8arr asegs ?mm' DST jd =>
        lazymatch goal with OU : u8arr asegs ?mq DST jd, MQ : munch [(SP1 + 80, SP1 + 88)] ?mq mm' |- _ =>
          eapply (u8arr_transport asegs _ mq mm'); [exact OU| exact MQ| eassumption| cbn [disjoint_from]; rewrite LJD;
            pose proof (spaf_props SPV SP16); pose proof (ablk_lin _ _ HDST); pose proof atop_range; unfold DEC_STACK in LO; lia] end
    | |- rw_cells asegs ?mm' (SP1 + 48) _ =>
        lazymatch goal with FS : rw_cells asegs ?mq (SP1 + 48) _, MQ : munch [(SP1 + 80, SP1 + 88)] ?mq mm' |- _ =>
          eapply (rw_cells_transport asegs _ mq mm'); [exact FS| exact MQ| eassumption| cbn; lia] end
    end.

  (* [comment removed for export] *)
  Lemma sdA_r3 : forall m d2r (st1 st2 : Z) jp (x1 x5 x6 x7 x10 x11 x12 x13 x14 x15 x16 x17 x21 x22 x23 x28 x29 x30 x31 : word),
    munch W0 m0 m -> wmono asegs m0 m -> mem_inv asegs m -> stk asegs m lo SP1 -> 0 < zlen bs -> u8arr asegs m DST jd ->
    rw_cells asegs m (SP1 + 48) [C8 (Z_to_bv 64 st2); C8 (Z_to_bv 64 TB); C8 (Z_to_bv 64 st1); C8 (Z_to_bv 64 TB)] ->
    rw_cells asegs m (SP1 + 80) (bitdz_cellsA S0 d2r jp) ->
    bitd_ok bs d2r -> 0 <= st1 < 2^tl -> 0 <= st2 < 2^tl ->
    RF_huf_fdw_st.res_ok (decompress_usingDTable bs d dcap false) ->
    decompress_usingDTable bs d dcap false =
      (let! r3 := reload_dstream bs d2r in let '(st, d3) := r3 in
       if dstatus_eqb st Overflow then Err ZSTD_error_corruption_detected
       else let! x := main_loop bs d dcap false (Datatypes.S (Z.to_nat dcap)) (mkDec [] st1 st2 d3) in
            tail_loop bs d dcap false (Datatypes.S (Z.to_nat dcap)) x) ->
    evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 SP1) gp tp x5 x6 x7 (Z_to_bv 64 SPV) (Z_to_bv 64 SP1) x10 x11 x12 x13 x14 x15 x16 x17
                            (Z_to_bv 64 FF) (Z_to_bv 64 (Z.shiftr FF 3 + 2147450880)) (Z_to_bv 64 AZEROFILLED) x21 x22 x23
                            (Z_to_bv 64 (DST + dcap)) (Z_to_bv 64 (DST + dcap - 3)) (Z_to_bv 64 DST) (Z_to_bv 64 2147450880)
                            x28 x29 x30 x31)
                        FR (Z_to_bv 64 0x961a4) fc None m (seg_rom asegs)).
Proof.
